class Solution:
    def largestTriangleArea(self, points):
        ans = 0.0
        for a, b, c in itertools.combinations(points, 3):
            ux, uy = b[0] - a[0], b[1] - a[1]
            vx, vy = c[0] - a[0], c[1] - a[1]
            ans = max(ans, abs(ux * vy - uy * vx) / 2)
        return ans

